CREATE TABLE rm_company_knowledge_assertions (
 id INTEGER PRIMARY KEY, assertion_id TEXT NOT NULL UNIQUE CHECK(length(assertion_id) BETWEEN 3 AND 80), company_slug TEXT NOT NULL CHECK(length(company_slug) BETWEEN 1 AND 120), predicate TEXT NOT NULL CHECK(predicate IN ('business_description','operating_status','products_services','revenue_models','markets','customer_types','industry_tags','operational_systems','document_sources','reporting_dimensions','responsible_party','canonical_reference')), value_json TEXT NOT NULL CHECK(length(value_json) BETWEEN 2 AND 32768), value_hash TEXT NOT NULL CHECK(length(value_hash)=64 AND value_hash NOT GLOB '*[^0-9a-f]*'), source_kind TEXT NOT NULL CHECK(source_kind IN ('user','registry','party','corporate_record','external_snapshot','canonical_setting')), source_ref TEXT NOT NULL CHECK(length(source_ref) BETWEEN 1 AND 512), valid_from TEXT NOT NULL, valid_to_exclusive TEXT, certainty TEXT NOT NULL CHECK(certainty IN ('confirmed','probable','uncertain')), actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160), principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service_account','local_operator')), principal_id TEXT NOT NULL CHECK(length(principal_id) BETWEEN 1 AND 160), created_at TEXT NOT NULL
);
CREATE TABLE rm_company_knowledge_events (
 id INTEGER PRIMARY KEY, assertion_id TEXT NOT NULL REFERENCES rm_company_knowledge_assertions(assertion_id), event_type TEXT NOT NULL CHECK(event_type IN ('proposed','approved','rejected','superseded')), reason TEXT, supersedes_assertion_id TEXT REFERENCES rm_company_knowledge_assertions(assertion_id), actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160), principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service_account','local_operator')), principal_id TEXT NOT NULL CHECK(length(principal_id) BETWEEN 1 AND 160), created_at TEXT NOT NULL
);
CREATE UNIQUE INDEX rm_company_knowledge_assertion_identity ON rm_company_knowledge_assertions(company_slug,predicate,value_hash,source_kind,source_ref,valid_from,COALESCE(valid_to_exclusive,''));
CREATE UNIQUE INDEX rm_company_knowledge_event_identity ON rm_company_knowledge_events(assertion_id,event_type,COALESCE(reason,''),COALESCE(supersedes_assertion_id,''));
CREATE INDEX rm_company_knowledge_assertions_scope_idx ON rm_company_knowledge_assertions(company_slug,predicate,valid_from,valid_to_exclusive);
CREATE INDEX rm_company_knowledge_events_assertion_idx ON rm_company_knowledge_events(assertion_id,id);
CREATE TRIGGER rm_company_knowledge_assertions_no_update BEFORE UPDATE ON rm_company_knowledge_assertions BEGIN SELECT RAISE(ABORT, 'company knowledge assertions are append-only'); END;
CREATE TRIGGER rm_company_knowledge_assertions_no_delete BEFORE DELETE ON rm_company_knowledge_assertions BEGIN SELECT RAISE(ABORT, 'company knowledge assertions are append-only'); END;
CREATE TRIGGER rm_company_knowledge_events_no_update BEFORE UPDATE ON rm_company_knowledge_events BEGIN SELECT RAISE(ABORT, 'company knowledge events are append-only'); END;
CREATE TRIGGER rm_company_knowledge_events_no_delete BEFORE DELETE ON rm_company_knowledge_events BEGIN SELECT RAISE(ABORT, 'company knowledge events are append-only'); END;
